class Solution {
public:
    long long minimumCost(int m, int n, vector<int>& horizontalCut, vector<int>& verticalCut) {
        sort(horizontalCut.rbegin(), horizontalCut.rend());
        sort(verticalCut.rbegin(), verticalCut.rend());
        long long ans = 0; int h = 0, v = 0, hp = 1, vp = 1;
        while (h < horizontalCut.size() && v < verticalCut.size()) {
            if (horizontalCut[h] >= verticalCut[v]) { ans += (long long)horizontalCut[h++] * vp; hp++; }
            else { ans += (long long)verticalCut[v++] * hp; vp++; }
        }
        while (h < horizontalCut.size()) ans += (long long)horizontalCut[h++] * vp;
        while (v < verticalCut.size()) ans += (long long)verticalCut[v++] * hp;
        return ans;
    }
};

