class Solution {
    public long minimumCost(int m, int n, int[] horizontalCut, int[] verticalCut) {
        Arrays.sort(horizontalCut);
        Arrays.sort(verticalCut);
        long ans = 0; int h = horizontalCut.length - 1, v = verticalCut.length - 1, hp = 1, vp = 1;
        while (h >= 0 && v >= 0) {
            if (horizontalCut[h] >= verticalCut[v]) { ans += (long)horizontalCut[h--] * vp; hp++; }
            else { ans += (long)verticalCut[v--] * hp; vp++; }
        }
        while (h >= 0) ans += (long)horizontalCut[h--] * vp;
        while (v >= 0) ans += (long)verticalCut[v--] * hp;
        return ans;
    }
}

