var minimumCost = function(m, n, horizontalCut, verticalCut) {
    horizontalCut.sort((a, b) => b - a);
    verticalCut.sort((a, b) => b - a);
    let ans = 0, h = 0, v = 0, hp = 1, vp = 1;
    while (h < horizontalCut.length && v < verticalCut.length) {
        if (horizontalCut[h] >= verticalCut[v]) { ans += horizontalCut[h++] * vp; hp++; }
        else { ans += verticalCut[v++] * hp; vp++; }
    }
    while (h < horizontalCut.length) ans += horizontalCut[h++] * vp;
    while (v < verticalCut.length) ans += verticalCut[v++] * hp;
    return ans;
};
